  @override
  String get legalDataConsentRetentionBody =>
      'মডেল ডেভেলপমেন্টের জন্য প্রয়োজনীয় সময়ের জন্য বেনামী প্রশিক্ষণ ডেটাসেটগুলি রাখা হয়, সাধারণত সৃষ্টির 24 মাস। ফাইন-টিউনিং ডেটাসেটগুলির জন্য 12 মাস পরে স্পষ্টভাবে পুনরায় সম্মতি প্রয়োজন। ভাড়াটে অ্যাকাউন্ট বন্ধ করার পরে, সেই ভাড়াটেদের বিষয়বস্তু থেকে প্রাপ্ত সমস্ত প্রশিক্ষণ ডেটা 60 দিনের মধ্যে পরিষ্কার করা হয়।';

