  @override
  String get legalDataConsentWhatIsTrainingBody =>
      'এই প্রেক্ষাপটে AI প্রশিক্ষণের অর্থ হল আপনার ডেটা ব্যবহার করা — বেনামীকরণ এবং ছদ্মনামকরণের পরে — এআই মডেলগুলির যথার্থতা, প্রাসঙ্গিকতা বা সুরক্ষা উন্নত করতে যা Umbrella বৈশিষ্ট্যগুলিকে শক্তিশালী করে। এর অর্থ এই নয় যে কোনো তৃতীয় পক্ষের সাথে শনাক্তযোগ্য ক্লায়েন্ট ডেটা ভাগ করা। প্রশিক্ষণ পাইপলাইনগুলি ডেটা-প্রসেসিং চুক্তির অধীনে DVTech Ventures বা এর চুক্তিবদ্ধ AI প্রদানকারীদের দ্বারা পরিচালিত হয়।';

