  @override
  String get legalDisclaimerAINotLawyerBody =>
      'আমব্রেলার এআই সিস্টেমগুলি সাধারণ আইনি সংস্থার উপর প্রশিক্ষিত বড় ভাষার মডেল। তারা অনুশীলনের শংসাপত্র ধারণ করে না, আদালতে হাজির হতে পারে না, কোনো বার অ্যাসোসিয়েশন বা আইন সমিতি দ্বারা নিয়ন্ত্রিত হয় না, এবং একজন আইনজীবী হিসাবে আপনার প্রতি যত্ন নেওয়ার কোনো দায়িত্ব দেন না। এআই আউটপুট হতে পারে: বাস্তবগত ত্রুটি বা হ্যালুসিনেশন থাকতে পারে; আপনার নির্দিষ্ট তথ্যের সাথে প্রাসঙ্গিক উপাদান বিবেচনা বাদ দিন; সংশোধিত, বাতিল, বা বাতিল করা হয়েছে এমন আইন বা মামলার উল্লেখ করুন; সাম্প্রতিক আইনী পরিবর্তনের জন্য অ্যাকাউন্টে ব্যর্থ; এবং জটিল বা অস্পষ্ট আইনি প্রশ্ন ভুল ব্যাখ্যা. আপনাকে অবশ্যই প্রতিটি AI আউটপুটকে তদন্তের জন্য একটি সূচনা পয়েন্ট হিসাবে বিবেচনা করতে হবে, চূড়ান্ত উত্তর নয়।';

