  @override
  String get legalDisclaimerJurisdictionBody =>
      'ভারত: এআই বিশ্লেষণ কেন্দ্রীয় আইন, রাষ্ট্রীয় আইন যেখানে নির্দিষ্ট করা হয়েছে এবং প্রকাশিত বিচারিক সিদ্ধান্তের উপর ভিত্তি করে তৈরি। এটি জেলা আদালত-স্তরের অনুশীলন, স্থানীয় বার কাস্টমস, বা কোডবিহীন পদ্ধতিগত নিয়মগুলির জন্য দায়ী নয়। মার্কিন যুক্তরাষ্ট্র: এআই বিশ্লেষণ ফেডারেল আইন এবং নির্বাচিত রাজ্য আইনের উপর ভিত্তি করে। মার্কিন আইনি বিশ্লেষণ রাষ্ট্র-নির্দিষ্ট লাইসেন্সপ্রাপ্ত পরামর্শের বিকল্প নয়। যাচাইকৃত আইনজীবী পর্যালোচনা ছাড়া অভিবাসন, ফৌজদারি প্রতিরক্ষা, বা ট্যাক্স সংক্রান্ত বিষয়ে উপলব্ধ নয়। কেনিয়া: কেনিয়ার আইন, সহায়ক আইন, এবং প্রকাশিত হাইকোর্ট এবং আপিলের সিদ্ধান্তের উপর বিশ্লেষণ করা হয়েছে। এটি প্রথাগত আইন, ম্যাজিস্ট্রেট আদালতের ভিন্নতা বা অপ্রকাশিত রায়গুলির জন্য দায়ী নয়। যুক্তরাজ্য: বিশ্লেষণ ইংরেজি এবং ওয়েলশ আইন কভার করে। স্কটস আইন, উত্তর আইরিশ আইন, এবং বিবর্তিত বিষয়গুলি উল্লেখযোগ্যভাবে ভিন্ন হতে পারে; এখতিয়ার-নির্দিষ্ট পরামর্শ চাইতে।';

