  @override
  String get legalTermsDefinitionsBody =>
      '\"প্ল্যাটফর্ম\" মানে umbrella.okaylegal.ai এবং সমস্ত সংশ্লিষ্ট অ্যাপ্লিকেশন, API এবং পরিষেবা। \"ভোক্তা ব্যবহারকারী\" মানে একজন স্বাভাবিক ব্যক্তি যে প্ল্যাটফর্ম ব্যবহার করে তাদের নিজস্ব আইনি পরিস্থিতি বোঝার জন্য। \"আইনজীবী ব্যবহারকারী\" মানে আইনজীবী OS বৈশিষ্ট্যগুলি ব্যবহার করে একজন লাইসেন্সপ্রাপ্ত আইনি পেশাদার৷ \"ভাড়াটিয়া\" অর্থ দৃঢ় সদস্যতা সহ একটি আইন সংস্থা বা সংস্থা৷ \"AI আউটপুট\" মানে Umbrella-এর AI সিস্টেম দ্বারা উত্পন্ন যেকোন পাঠ্য, বিশ্লেষণ, খসড়া বা সুপারিশ। \"ম্যাটার\" মানে আইনজীবী OS এর মাধ্যমে পরিচালিত একটি আইনি মামলা বা লেনদেন। \"DVTech Ventures\" বা \"we\" মানে প্ল্যাটফর্মের অপারেটর।';

  @override
  String get legalTermsDefinitionsHeading => '2. সংজ্ঞা';

  @override
  String get legalTermsDescription =>
      'আমব্রেলা ভোক্তা এবং আইনজীবী প্ল্যাটফর্ম ব্যবহার করার নিয়ম।';

  @override
  String get legalTermsDisputeBody =>
      'ভারত ব্যবহারকারী: এই শর্তাবলী ভারতের আইন দ্বারা নিয়ন্ত্রিত হয়; বিরোধগুলি বেঙ্গালুরুতে বসে সালিসি ও সমঝোতা আইন 1996 এর অধীনে বাধ্যতামূলক সালিসি দ্বারা সমাধান করা হবে। ইউনাইটেড স্টেটস ব্যবহারকারী: ডেলাওয়্যারে বসে থাকা AAA বাণিজ্যিক সালিসি নিয়মের অধীনে বাধ্যতামূলক সালিসি দ্বারা বিরোধগুলি সমাধান করা হবে; বর্গ কর্ম মওকুফ প্রযোজ্য. কেনিয়ার ব্যবহারকারী: এই শর্তাবলী কেনিয়ার আইন দ্বারা নিয়ন্ত্রিত হয়; নাইরোবি সেন্টার ফর ইন্টারন্যাশনাল আরবিট্রেশন (NCIA) নিয়মের অধীনে বিরোধগুলি সমাধান করা হবে। ইউনাইটেড কিংডম ব্যবহারকারী: এই শর্তাবলী ইংরেজি আইন দ্বারা পরিচালিত হয়; বিরোধগুলি ইংল্যান্ড এবং ওয়েলসের আদালতের একচেটিয়া এখতিয়ারে জমা দেওয়া হবে। সব ক্ষেত্রেই, উপযুক্ত আদালতের কাছ থেকে জরুরী নিষেধাজ্ঞামূলক ত্রাণ চাওয়ার ক্ষেত্রে কিছুই আপনাকে বাধা দেয় না।';

  @override
  String get legalTermsDisputeHeading => '18. বিরোধ নিষ্পত্তি এবং পরিচালনা আইন';

  @override
  String get legalTermsIPContentBody =>
      'আপনি প্ল্যাটফর্মে জমা দেওয়া সমস্ত সামগ্রীর মালিকানা বজায় রাখেন। বিষয়বস্তু জমা দেওয়ার মাধ্যমে আপনি DVTech Ventures কে একটি বিশ্বব্যাপী, রয়্যালটি-মুক্ত, অ-এক্সক্লুসিভ লাইসেন্স প্রদান করেন যা শুধুমাত্র পরিষেবাগুলি সরবরাহ করার জন্য আপনার সামগ্রী প্রক্রিয়াকরণ, সঞ্চয় এবং প্রদর্শনের জন্য। এই লাইসেন্সটি AI প্রশিক্ষণে প্রসারিত হয় না যদি না আপনি ডেটা এবং AI সম্মতি নীতির অধীনে নির্বাচন করেন।';

  @override
  String get legalTermsIPHeading => '12. মেধা সম্পত্তি';

  @override
  String get legalTermsIPPlatformBody =>
      'DVTech Ventures আমব্রেলা প্ল্যাটফর্ম, ব্র্যান্ড, অন্তর্নিহিত AI মডেল এবং প্রযুক্তির সমস্ত অধিকারের মালিক। আপনার সাবস্ক্রিপশনের সময়কালের জন্য প্ল্যাটফর্মটি ব্যবহার করার জন্য আপনাকে একটি সীমিত, অ-এক্সক্লুসিভ, অ-হস্তান্তরযোগ্য লাইসেন্স দেওয়া হয়েছে।';

  @override
  String get legalTermsIndemnityBody =>
      'আপনি ক্ষতিপূরণ দিতে, রক্ষা করতে এবং ধারণ করতে সম্মত হন ক্ষতিকারক DVTech ভেঞ্চারস এবং এর কর্মকর্তা, পরিচালক, কর্মচারী এবং এজেন্টদের যেকোন দাবি, ক্ষতি, ক্ষতি এবং খরচ (যুক্তিসঙ্গত আইনি ফি সহ) থেকে এবং এর বিরুদ্ধে: (ক) এই শর্তাবলী লঙ্ঘন করে আপনার প্ল্যাটফর্মের ব্যবহার; (খ) আপনার কোন প্রযোজ্য আইন লঙ্ঘন; (গ) আপনার জমা দেওয়া সামগ্রী যা তৃতীয় পক্ষের অধিকার লঙ্ঘন করে; (d) আইনি পরামর্শ বা পরিষেবা যা আপনি প্ল্যাটফর্ম ব্যবহার করে আপনার ক্লায়েন্টদের প্রদান করেন।';

  @override
  String get legalTermsIndemnityHeading => '17. ক্ষতিপূরণ';

  @override
  String get legalTermsLawyerUsersBody =>
      'আইনজীবী ব্যবহারকারীরা স্বাধীন লাইসেন্সপ্রাপ্ত পেশাদার। আইনজীবী ওএস ব্যবহার করে, আপনি নিশ্চিত করেন যে আপনি আপনার এখতিয়ারে একটি বৈধ অনুশীলনের শংসাপত্র ধারণ করেছেন এবং আপনি প্রযোজ্য পেশাদার আচরণের নিয়ম এবং বার প্রবিধান মেনে প্ল্যাটফর্মটি ব্যবহার করবেন। আপনি আপনার ক্লায়েন্টদের প্রদান করা সমস্ত আইনি কাজ এবং পরামর্শের গুণমান এবং বৈধতার জন্য সম্পূর্ণরূপে দায়ী থাকবেন। ছাতা সরঞ্জাম সরবরাহ করে — এটি আইনজীবী ব্যবহারকারীদের পেশাদার আচরণের তত্ত্বাবধান বা গ্যারান্টি দেয় না।';

  @override
