  @override
  String get legalTermsPermittedUseBody =>
      'আপনি প্ল্যাটফর্মটি ব্যবহার করতে পারেন: ব্যক্তিগত বা পেশাদার ব্যবহারের জন্য AI-উত্পন্ন আইনি তথ্য পেতে; আইনি বিষয়, ক্লায়েন্ট, বিলিং এবং নথি (আইনজীবী ওএস) পরিচালনা করুন; লাইসেন্সপ্রাপ্ত অ্যাটর্নিদের সাথে সংযোগ স্থাপনের জন্য আইনজীবীর বাজারে প্রবেশ করুন; এবং আমাদের নথিভুক্ত API এর মাধ্যমে আপনার সিস্টেমের সাথে প্ল্যাটফর্মকে একীভূত করুন।';

  @override
