  @override
  String get legalTermsProhibitedUseBody =>
      'আপনি অবশ্যই: (ক) একজন আইনজীবী, বিচারক বা সরকারী কর্মকর্তার ছদ্মবেশ ধারণ করবেন না; (b) আইনজীবী পর্যালোচনা ছাড়াই তৃতীয় পক্ষের কাছে আনুষ্ঠানিক আইনি পরামর্শ হিসাবে AI আউটপুট ব্যবহার করুন; (গ) বেআইনি, মানহানিকর, বা প্রতারণামূলক সামগ্রী জমা দেওয়া; (d) অন্তর্নিহিত AI মডেল বা প্রশিক্ষণ ডেটা রিভার্স-ইঞ্জিনিয়ার, স্ক্র্যাপ বা বের করার চেষ্টা করা; (ঙ) লিখিত সম্মতি ছাড়াই প্ল্যাটফর্মে পুনরায় বিক্রয় বা সাবলাইসেন্স অ্যাক্সেস; (f) ডেটা সুরক্ষা, ভোক্তা সুরক্ষা, এবং আইনি পেশার নিয়মগুলি সহ প্রযোজ্য আইন লঙ্ঘন করে এমন কোনও উপায়ে প্ল্যাটফর্মটি ব্যবহার করুন; (g) তৃতীয় পক্ষের মেধা সম্পত্তি অধিকার লঙ্ঘন করে এমন সামগ্রী জমা দিন৷';

  @override
  String get legalTermsProhibitedUseHeading => '5. নিষিদ্ধ ব্যবহার';

  @override
  String get legalTermsRefundBody =>
      'আপনি অ্যাকাউন্ট সেটিংস থেকে যেকোনো সময় আপনার সদস্যতা বাতিল করতে পারেন। বাতিলকরণ বর্তমান বিলিং সময়ের শেষে কার্যকর হয়; অব্যবহৃত সময়ের জন্য কোন আংশিক ফেরত জারি করা হয় না। আপনি যদি বিশ্বাস করেন যে আপনাকে ভুল করে চার্জ করা হয়েছে, তাহলে চার্জের ৩০ দিনের মধ্যে support@odaflow.com-এ যোগাযোগ করুন। আমরা পর্যালোচনা করব এবং উপযুক্ত হলে, আমাদের বিবেচনার ভিত্তিতে প্রো-রাটা ফেরত ইস্যু করব।';

  @override
  String get legalTermsRefundHeading => '8. রিফান্ড এবং বাতিলকরণ';

  @override
  String get legalTermsSeverabilityBody =>
      'যদি এই শর্তাবলীর কোনো বিধান অপ্রয়োগযোগ্য বলে পাওয়া যায়, বাকি বিধানগুলি সম্পূর্ণরূপে অব্যাহত থাকে। কোনো অধিকার প্রয়োগে আমাদের ব্যর্থতা সেই অধিকারের পরিত্যাগ নয়। এই শর্তাবলী, গোপনীয়তা নীতি এবং ডেটা এবং AI সম্মতি নীতির সাথে, প্ল্যাটফর্ম সম্পর্কিত আপনার এবং DVTech Ventures-এর মধ্যে সম্পূর্ণ চুক্তি গঠন করে।';

  @override
  String get legalTermsSeverabilityHeading => '19. সাধারণ';

  @override
  String get legalTermsSubscriptionBody =>
      'প্রদত্ত পরিকল্পনাগুলি একটি মাসিক বা বার্ষিক চক্রে অগ্রিম বিল করা হয়। মূল্য চেকআউটের সময় আপনার স্থানীয় মুদ্রায় প্রদর্শিত হয় এবং প্রযোজ্য কর অন্তর্ভুক্ত হতে পারে। সদস্যতা প্রতিটি বিলিং সময়ের শেষে স্বয়ংক্রিয়ভাবে পুনর্নবীকরণ হয় যদি না আপনি পুনর্নবীকরণ তারিখের আগে বাতিল করেন। অর্থ প্রদানে ব্যর্থতার ফলে অ্যাক্সেস স্থগিত বা সমাপ্ত হতে পারে।';

